const D = { energy:.6, scale:1, speed:1, density:.5, feed:.037, kill:.062, hue:190, x:.5, y:.5, style:'coral', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;
const W=width,H=height,u=Math.min(W,H);
const hsh=i=>{const s=Math.sin(i*127.1+(P.seed|0)*311.7)*43758.5453;return s-Math.floor(s);};

// ---- coarse Gray-Scott grid, size + seed keyed (<=164 wide) ----
const LS=148;
const GW=Math.max(48,Math.min(164,Math.round(LS*W/Math.max(W,H))));
const GH=Math.max(28,Math.min(104,Math.round(LS*H/Math.max(W,H))));
const N=GW*GH;
if(!S.a || S.gw!==GW || S.gh!==GH || S.seedUsed!==(P.seed|0)){
  S.gw=GW; S.gh=GH; S.seedUsed=(P.seed|0);
  S.a=new Float32Array(N); S.b=new Float32Array(N);
  S.a2=new Float32Array(N); S.b2=new Float32Array(N);
  for(let i=0;i<N;i++){ S.a[i]=1; S.b[i]=0; }        // U=1 everywhere, V=0
  const patches=44+Math.round(hsh(1)*40);             // many scattered V seed patches -> edge-to-edge morphogenesis
  for(let s=0;s<patches;s++){
    const cx=Math.floor(hsh(s*4+2)*GW), cy=Math.floor(hsh(s*4+3)*GH), rr=1+Math.floor(hsh(s*4+5)*3);
    for(let dy=-rr;dy<=rr;dy++)for(let dx=-rr;dx<=rr;dx++){
      if(dx*dx+dy*dy>rr*rr)continue;
      const x=((cx+dx)%GW+GW)%GW, y=((cy+dy)%GH+GH)%GH;
      S.b[y*GW+x]=0.9;
    }
  }
  if(!S.buf || S.bkw!==GW || S.bkh!==GH){ if(S.buf&&S.buf.remove)S.buf.remove(); S.buf=createGraphics(GW,GH); S.buf.pixelDensity(1); S.bkw=GW; S.bkh=GH; }
  S.burn=10;   // burn-in spread over the first ~10 frames (~0.17s) so the pattern is grown before any capture (no single-frame fps stall)
}
const a=S.a,b=S.b,a2=S.a2,b2=S.b2,buf=S.buf;

// ---- regime sweep: march a ring of LIVING Gray-Scott waypoints over minutes ----
// mitosis -> spots -> fine-maze -> fingerprint -> holes -> coral -> (loop). Every waypoint AND
// every interpolated midpoint stays in the living zone, so the field NEVER dies (Gray-Scott can't
// recover from an all-dead field). P.feed/P.kill offset the whole ring warmer/colder.
const REG=[[0.037,0.062],[0.030,0.062],[0.026,0.055],[0.029,0.057],[0.039,0.058],[0.052,0.062]];
const nR=REG.length;
const phase=K.section*0.7 + K.t*(0.010+P.speed*0.012);   // minutes-scale march; K.t term = never static
const fp=((phase%nR)+nR)%nR, ri=fp|0, rt=fp-ri, w0=REG[ri], w1=REG[(ri+1)%nR];
const baseF=w0[0]+(w1[0]-w0[0])*rt, baseK=w0[1]+(w1[1]-w0[1])*rt;
const feedC=clp(baseF+(P.feed-0.037),0.014,0.086);
const killC=clp(baseK+(P.kill-0.062),0.030,0.070);
const DA=1.0, DB=0.5;

// ---- perpetual V injector: motion floor + never-freeze; audio only ADDS ----
const dens=clp(P.density,0,1);
const injN=1+Math.round(dens*2);
for(let q=0;q<injN;q++){
  const ang=K.t*(0.19+q*0.09)+q*2.3, rad=0.22+0.15*Math.sin(K.t*0.05+q*1.7);
  const ix=Math.floor((0.5+(P.x-0.5)*0.5+Math.cos(ang)*rad)*GW);
  const iy=Math.floor((0.5+(P.y-0.5)*0.5+Math.sin(ang)*rad)*GH);
  const rr=1+Math.round(dens*2), amp=0.30+A.bass*0.4+K.pulse*0.15;
  for(let dy=-rr;dy<=rr;dy++)for(let dx=-rr;dx<=rr;dx++){
    if(dx*dx+dy*dy>rr*rr)continue;
    const x=((ix+dx)%GW+GW)%GW, y=((iy+dy)%GH+GH)%GH, idx=y*GW+x;
    b[idx]=Math.min(1,b[idx]+amp*0.5);
  }
}

// ---- iterate Gray-Scott: 9-pt isotropic Laplacian, toroidal wrap; >=1 step/frame = motion floor ----
let iters=Math.max(1,Math.round((1.2+P.speed*1.3)*(0.7+0.6*K.intensity)));
if(iters>7) iters=7;
if(S.burn>0){ iters+=30; S.burn--; }   // accelerated cook for the first frames, then off
let sa=a,sb=b,da=a2,db=b2;
for(let it=0;it<iters;it++){
  for(let y=0;y<GH;y++){
    const ym=(y-1+GH)%GH, yp=(y+1)%GH, r0=ym*GW, r1=y*GW, r2=yp*GW;
    for(let x=0;x<GW;x++){
      const xm=(x-1+GW)%GW, xp=(x+1)%GW, i=r1+x;
      const av=sa[i], bv=sb[i];
      const la=0.2*(sa[r1+xm]+sa[r1+xp]+sa[r0+x]+sa[r2+x])+0.05*(sa[r0+xm]+sa[r0+xp]+sa[r2+xm]+sa[r2+xp])-av;
      const lb=0.2*(sb[r1+xm]+sb[r1+xp]+sb[r0+x]+sb[r2+x])+0.05*(sb[r0+xm]+sb[r0+xp]+sb[r2+xm]+sb[r2+xp])-bv;
      const rea=av*bv*bv;
      let na=av+(DA*la-rea+feedC*(1-av));
      let nb=bv+(DB*lb+rea-(killC+feedC)*bv);
      da[i]=na<0?0:na>1?1:na; db[i]=nb<0?0:nb>1?1:nb;
    }
  }
  const ta=sa;sa=da;da=ta; const tb=sb;sb=db;db=tb;
}
if(sa!==S.a){ S.a.set(sa); S.b.set(sb); }
const fld=S.b;

// ---- field V -> RGB straight into buffer pixels (RAW RGBA bytes — the HSB mode does not touch these) ----
const gain=1.6+clp(P.energy,0,1)*3.2, st=P.style;
buf.loadPixels(); const px=buf.pixels;
function ramp(stops,f){ const n=stops.length-1, ff=clp(f,0,1)*n; let k=ff|0; if(k>=n)k=n-1; const t=ff-k, s0=stops[k], s1=stops[k+1]; return [s0[0]+(s1[0]-s0[0])*t, s0[1]+(s1[1]-s0[1])*t, s0[2]+(s1[2]-s0[2])*t]; }
const CORAL=[[8,40,52],[16,120,138],[70,205,205],[240,225,95],[245,72,150]];
const THERM=[[4,2,14],[70,10,90],[190,30,30],[245,140,20],[255,245,190]];
const MOSS=[[10,24,12],[45,95,40],[110,140,55],[180,170,80],[222,206,138]];
for(let y=0;y<GH;y++)for(let x=0;x<GW;x++){
  const i=y*GW+x;
  let f=clp((fld[i]-0.02)*gain,0,1), r,g,bl;
  if(st==='coral'){ const c=ramp(CORAL,f); r=c[0]; g=c[1]; bl=c[2]; }
  else if(st==='thermal'){ const c=ramp(THERM,Math.pow(f,0.9)); r=c[0]; g=c[1]; bl=c[2]; }
  else if(st==='moss'){ const c=ramp(MOSS,f); r=c[0]; g=c[1]; bl=c[2]; }
  else if(st==='bone'){ // x-ray radiograph: bone-white structures edge-lit on dark navy
    const xm=(x-1+GW)%GW, xp=(x+1)%GW, ym=(y-1+GH)%GH, yp=(y+1)%GH;
    const gx=fld[y*GW+xp]-fld[y*GW+xm], gy=fld[yp*GW+x]-fld[ym*GW+x];
    const e=clp(Math.hypot(gx,gy)*gain*2.6,0,1);
    const m=clp(Math.pow(f,0.8)+e*0.6,0,1);
    r=10+m*220; g=14+m*226; bl=26+m*230;
  } else { // ink-maze: black fingerprint ink on warm cream paper
    const ink=clp(Math.pow(f,0.85),0,1), tone=1-ink*0.93;
    r=242*tone+3; g=232*tone+3; bl=206*tone+3;
  }
  const j=i*4; px[j]=clp(r,0,255); px[j+1]=clp(g,0,255); px[j+2]=clp(bl,0,255); px[j+3]=255;
}
buf.updatePixels();

// ---- composite: upscale to full frame; P.scale = display zoom on a centered sub-rect ----
const zoom=clp(P.scale,1,2.6), sw=GW/zoom, sh=GH/zoom;
const sx=clp((GW-sw)*(0.15+P.x*0.7),0,GW-sw), sy=clp((GH-sh)*(0.15+P.y*0.7),0,GH-sh);
noStroke(); drawingContext.imageSmoothingEnabled=true;
push();
if(P.alpha<100) tint(0,0,100,clp(P.alpha,0,100));
image(buf,0,0,W,H,sx,sy,sw,sh);
pop();

// ---- finishing (PARTIAL-frame only — never a full-frame flash) ----
if(st!=='ink-maze'){
  blendMode(ADD); noStroke();
  const hb=(((P.hue%360)+360)%360);
  const gl=clp((7+9*K.swell+A.bass*16+A.rms*10)*0.6,0,13);
  fill(hb, st==='bone'?18:42, 100, gl);
  rect(0,0,W,H);
  blendMode(BLEND);
} else { // cream never reads flat: faint warm vignette frame
  noFill(); strokeWeight(u*0.14); stroke(35,12,52,9); rect(-u*0.07,-u*0.07,W+u*0.14,H+u*0.14); noStroke();
}
blendMode(BLEND); drawingContext.shadowBlur=0; noStroke();
